package com.smartexam.mvp;

import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.smartexam.entity.*;import com.smartexam.security.JwtService;import com.smartexam.service.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc @Transactional class MvpWorkflowIntegrationTest{
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired UsersService users;@Autowired CoursesService courses;@Autowired CourseStudentsService memberships;@Autowired ExamsService exams;@Autowired QuestionsService questions;@Autowired ScoringPointsService points;@Autowired SubmissionsService submissions;@Autowired AnswersService answers;@Autowired AiGradingResultsService aiResults;@Autowired StudentExamService studentExams;@Autowired JwtService jwt;
 String student,teacher;Long examId,singleId,shortId;
 @BeforeEach void setup(){Users t=users.findByUsername("teacher_demo"),s=users.findByUsername("student_demo_1");teacher=jwt.generate(t);student=jwt.generate(s);Courses c=new Courses();c.setTeacherId(t.getId());c.setCourseName("MVP闭环测试");courses.save(c);CourseStudents cs=new CourseStudents();cs.setCourseId(c.getId());cs.setStudentId(s.getId());cs.setStatus(1);memberships.save(cs);Exams e=new Exams();e.setCourseId(c.getId());e.setTitle("可作答考试");e.setDescription("集成测试");e.setStartTime(LocalDateTime.now().minusMinutes(5));e.setEndTime(LocalDateTime.now().plusMinutes(30));e.setLateEntryMinutes(10);e.setMinSubmitMinutes(0);e.setStatus("PUBLISHED");e.setCreatedBy(t.getId());exams.save(e);examId=e.getId();Questions q=new Questions();q.setExamId(examId);q.setQuestionType("SINGLE_CHOICE");q.setContent("2+2=?");q.setScore(new BigDecimal("5"));q.setOptionsJson("[{\"key\":\"A\",\"text\":\"4\"},{\"key\":\"B\",\"text\":\"3\"},{\"key\":\"C\",\"text\":\"2\"},{\"key\":\"D\",\"text\":\"1\"}]");q.setReferenceAnswer("A");q.setSortOrder(1);questions.save(q);singleId=q.getId();q=new Questions();q.setExamId(examId);q.setQuestionType("SHORT_ANSWER");q.setContent("说明JWT");q.setScore(new BigDecimal("10"));q.setReferenceAnswer("签名令牌");q.setSortOrder(2);questions.save(q);shortId=q.getId();ScoringPoints p=new ScoringPoints();p.setQuestionId(shortId);p.setPointContent("签名");p.setPointScore(new BigDecimal("10"));p.setSortOrder(1);points.save(p);}
 JsonNode call(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder r,Object body,String token,int status)throws Exception{r.header("Authorization","Bearer "+token);if(body!=null)r.contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body));String value=mvc.perform(r).andExpect(status().is(status)).andReturn().getResponse().getContentAsString();return json.readTree(value);}
 Long exam(Long courseId,String title,String status){Exams e=new Exams();e.setCourseId(courseId);e.setTitle(title);e.setStartTime(LocalDateTime.now().minusMinutes(5));e.setEndTime(LocalDateTime.now().plusMinutes(30));e.setLateEntryMinutes(10);e.setMinSubmitMinutes(0);e.setStatus(status);e.setCreatedBy(users.findByUsername("teacher_demo").getId());exams.save(e);return e.getId();}
 Long single(String content,String score,int sortOrder){Questions q=new Questions();q.setExamId(examId);q.setQuestionType("SINGLE_CHOICE");q.setContent(content);q.setScore(new BigDecimal(score));q.setOptionsJson("[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"},{\"key\":\"C\",\"text\":\"选项C\"},{\"key\":\"D\",\"text\":\"选项D\"}]");q.setReferenceAnswer("A");q.setSortOrder(sortOrder);questions.save(q);return q.getId();}
 void assertStudentPayloadSafe(JsonNode payload){assertThat(payload.toString()).doesNotContain("referenceAnswer","scoringPoints","autoScore","teacherScore","teacherComment","gradingStatus","aiSuggestion","aiScore","aiReason","aiComment","matchedPoints","missingPoints","totalScore");}
 @Test void studentCompletesWorkflowWithoutSensitiveFields()throws Exception{
  Long courseId=exams.getById(examId).getCourseId(),gradingId=exam(courseId,"阅卷中考试","GRADING"),releasedId=exam(courseId,"已发布成绩考试","RELEASED");Courses other=new Courses();other.setTeacherId(users.findByUsername("teacher_demo").getId());other.setCourseName("未加入课程");courses.save(other);Long otherPublishedId=exam(other.getId(),"其他课程考试","PUBLISHED");
  JsonNode list=call(get("/api/student/exams"),null,student,200);assertStudentPayloadSafe(list);List<Long> visibleIds=new ArrayList<>();list.path("data").forEach(candidate->visibleIds.add(candidate.path("id").asLong()));assertThat(visibleIds).contains(examId).doesNotContain(gradingId,releasedId,otherPublishedId);
  call(get("/api/student/exams/"+gradingId),null,student,404);call(get("/api/student/exams/"+releasedId),null,student,404);call(get("/api/student/exams/"+otherPublishedId),null,student,404);
  JsonNode detail=call(get("/api/student/exams/"+examId),null,student,200);assertStudentPayloadSafe(detail);
  JsonNode paper=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data");assertStudentPayloadSafe(paper);Long sid=paper.path("submissionId").asLong();
  JsonNode saved=call(put("/api/student/submissions/"+sid+"/answers/"+singleId),Map.of("answerContent","A"),student,200).path("data");assertStudentPayloadSafe(saved);assertThat(saved.path("questions").findValue("answerContent").asText()).isEqualTo("A");
  call(put("/api/student/submissions/"+sid+"/answers/"+shortId),Map.of("answerContent","JWT由签名保护"),student,200);
  JsonNode refreshed=call(get("/api/student/submissions/"+sid+"/paper"),null,student,200).path("data");assertStudentPayloadSafe(refreshed);assertThat(refreshed.path("questions").get(0).path("answerContent").asText()).isEqualTo("A");assertThat(refreshed.path("questions").get(1).path("answerContent").asText()).isEqualTo("JWT由签名保护");
  JsonNode reentered=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data");assertStudentPayloadSafe(reentered);assertThat(reentered.path("submissionId").asLong()).isEqualTo(sid);assertThat(reentered.path("questions").get(0).path("answerContent").asText()).isEqualTo("A");
  call(post("/api/student/submissions/"+sid+"/submit"),null,student,200);assertThat(submissions.getById(sid).getStatus()).isEqualTo("SUBMITTED");assertThat(answers.findOne(sid,singleId).getAutoScore()).isEqualByComparingTo("5");
  JsonNode submittedList=call(get("/api/student/exams"),null,student,200);assertStudentPayloadSafe(submittedList);JsonNode submittedExam=null;for(JsonNode candidate:submittedList.path("data")){if(candidate.path("id").asLong()==examId){submittedExam=candidate;break;}}assertThat(submittedExam).isNotNull();assertThat(submittedExam.path("submissionStatus").asText()).isEqualTo("SUBMITTED");
  call(post("/api/student/exams/"+examId+"/enter"),null,student,409);call(get("/api/student/submissions/"+sid+"/paper"),null,student,409);call(post("/api/student/submissions/"+sid+"/submit"),null,student,409);call(get("/api/student/results/"+sid),null,student,403);
 }
 @Test void teacherReviewsAiConfigurationAndPublishes()throws Exception{Long sid=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data").path("submissionId").asLong();call(put("/api/student/submissions/"+sid+"/answers/"+shortId),Map.of("answerContent","签名"),student,200);call(post("/api/student/submissions/"+sid+"/submit"),null,student,200);Answers shortAnswer=answers.findOne(sid,shortId);JsonNode ai=call(post("/api/teacher/grading/answers/"+shortAnswer.getId()+"/ai-grade"),null,teacher,200);assertThat(ai.toString()).contains("AI服务未配置").doesNotContain("SUCCESS");call(put("/api/teacher/grading/answers/"+shortAnswer.getId()+"/review"),Map.of("teacherScore",8,"teacherComment","要点基本完整"),teacher,200);call(put("/api/teacher/grading/submissions/"+sid+"/comment"),Map.of("teacherComment","继续努力"),teacher,200);call(post("/api/teacher/grading/submissions/"+sid+"/publish"),null,teacher,200);JsonNode result=call(get("/api/student/results/"+sid),null,student,200).path("data");assertThat(result.path("totalScore").decimalValue()).isEqualByComparingTo("8");assertThat(result.path("teacherComment").asText()).isEqualTo("继续努力");}
 @Test void examRulesRejectBeforeStartAndAllowFirstEntryWithinLateWindow()throws Exception{Exams e=exams.getById(examId);e.setStartTime(LocalDateTime.now().plusMinutes(2));e.setEndTime(LocalDateTime.now().plusMinutes(30));exams.updateById(e);call(post("/api/student/exams/"+examId+"/enter"),null,student,409);e.setStartTime(LocalDateTime.now().minusMinutes(5));e.setLateEntryMinutes(10);exams.updateById(e);Long sid=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data").path("submissionId").asLong();Submissions s=submissions.getById(sid);assertThat(s.getStatus()).isEqualTo("IN_PROGRESS");assertThat(s.getFirstEnterTime()).isNotNull();}
 @Test void examRulesRejectLateFirstEntryButAllowInProgressReentryAndUpdateTimestamps()throws Exception{Exams e=exams.getById(examId);e.setStartTime(LocalDateTime.now().minusMinutes(20));e.setEndTime(LocalDateTime.now().plusMinutes(30));e.setLateEntryMinutes(5);exams.updateById(e);call(post("/api/student/exams/"+examId+"/enter"),null,student,409);e.setLateEntryMinutes(30);exams.updateById(e);Long sid=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data").path("submissionId").asLong();Submissions s=submissions.getById(sid);LocalDateTime originalFirst=LocalDateTime.now().minusMinutes(2).truncatedTo(java.time.temporal.ChronoUnit.MILLIS);s.setFirstEnterTime(originalFirst);s.setLastEnterTime(originalFirst);submissions.updateById(s);e.setLateEntryMinutes(5);exams.updateById(e);call(post("/api/student/exams/"+examId+"/enter"),null,student,200);Submissions reentered=submissions.getById(sid);assertThat(reentered.getStatus()).isEqualTo("IN_PROGRESS");assertThat(reentered.getFirstEnterTime()).isEqualTo(originalFirst);assertThat(reentered.getLastEnterTime()).isAfter(originalFirst);}
 @Test void examRulesEnforceMinimumSubmitTimeThenAllowSubmission()throws Exception{Exams e=exams.getById(examId);e.setStartTime(LocalDateTime.now().minusMinutes(5));e.setMinSubmitMinutes(10);exams.updateById(e);Long sid=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data").path("submissionId").asLong();call(post("/api/student/submissions/"+sid+"/submit"),null,student,409);assertThat(submissions.getById(sid).getStatus()).isEqualTo("IN_PROGRESS");e.setStartTime(LocalDateTime.now().minusMinutes(11));exams.updateById(e);call(post("/api/student/submissions/"+sid+"/submit"),null,student,200);assertThat(submissions.getById(sid).getStatus()).isEqualTo("SUBMITTED");}
 @Test void examRulesAutoSubmitExpiredInProgressSubmission()throws Exception{Long sid=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data").path("submissionId").asLong();Exams e=exams.getById(examId);e.setEndTime(LocalDateTime.now().minusSeconds(1));exams.updateById(e);studentExams.autoSubmitExpired();Submissions expired=submissions.getById(sid);assertThat(expired.getStatus()).isEqualTo("AUTO_SUBMITTED");assertThat(expired.getSubmitTime()).isNotNull();}
 @Test void examRulesLockSubmittedSubmission()throws Exception{Long sid=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data").path("submissionId").asLong();call(post("/api/student/submissions/"+sid+"/submit"),null,student,200);call(post("/api/student/exams/"+examId+"/enter"),null,student,409);call(get("/api/student/submissions/"+sid+"/paper"),null,student,409);call(put("/api/student/submissions/"+sid+"/answers/"+singleId),Map.of("answerContent","B"),student,409);call(post("/api/student/submissions/"+sid+"/submit"),null,student,409);}
 @Test void singleChoiceAutoGradesCorrectWrongAndBlankOnManualSubmitWithoutLeakingGradingData()throws Exception{Long wrongId=single("错误答案题","7",3),blankId=single("空答案题","9",4);assertStudentPayloadSafe(call(get("/api/student/exams"),null,student,200));assertStudentPayloadSafe(call(get("/api/student/exams/"+examId),null,student,200));JsonNode entered=call(post("/api/student/exams/"+examId+"/enter"),null,student,200);assertStudentPayloadSafe(entered);Long sid=entered.path("data").path("submissionId").asLong();assertStudentPayloadSafe(call(put("/api/student/submissions/"+sid+"/answers/"+singleId),Map.of("answerContent","A"),student,200));assertStudentPayloadSafe(call(put("/api/student/submissions/"+sid+"/answers/"+wrongId),Map.of("answerContent","B"),student,200));assertStudentPayloadSafe(call(put("/api/student/submissions/"+sid+"/answers/"+shortId),Map.of("answerContent","简答内容"),student,200));assertStudentPayloadSafe(call(get("/api/student/submissions/"+sid+"/paper"),null,student,200));call(post("/api/student/submissions/"+sid+"/submit"),null,student,200);assertThat(answers.findOne(sid,singleId).getAutoScore()).isEqualByComparingTo("5");assertThat(answers.findOne(sid,wrongId).getAutoScore()).isEqualByComparingTo("0");assertThat(answers.findOne(sid,blankId).getAutoScore()).isEqualByComparingTo("0");Answers shortAnswer=answers.findOne(sid,shortId);assertThat(shortAnswer.getAutoScore()).isNull();assertThat(shortAnswer.getGradingStatus()).isEqualTo("PENDING");assertThat(submissions.getById(sid).getTotalScore()).isEqualByComparingTo("5");assertStudentPayloadSafe(call(get("/api/student/exams"),null,student,200));assertStudentPayloadSafe(call(get("/api/student/exams/"+examId),null,student,200));}
 @Test void singleChoiceAutoGradesTheSameOnAutoSubmitAndRepeatedScanIsIdempotent()throws Exception{Long wrongId=single("自动提交错误题","7",3),blankId=single("自动提交空题","9",4);Long sid=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data").path("submissionId").asLong();call(put("/api/student/submissions/"+sid+"/answers/"+singleId),Map.of("answerContent","A"),student,200);call(put("/api/student/submissions/"+sid+"/answers/"+wrongId),Map.of("answerContent","B"),student,200);call(put("/api/student/submissions/"+sid+"/answers/"+shortId),Map.of("answerContent","简答内容"),student,200);Exams e=exams.getById(examId);e.setEndTime(LocalDateTime.now().minusSeconds(1));exams.updateById(e);studentExams.autoSubmitExpired();assertThat(submissions.getById(sid).getStatus()).isEqualTo("AUTO_SUBMITTED");assertThat(answers.findOne(sid,singleId).getAutoScore()).isEqualByComparingTo("5");assertThat(answers.findOne(sid,wrongId).getAutoScore()).isEqualByComparingTo("0");assertThat(answers.findOne(sid,blankId).getAutoScore()).isEqualByComparingTo("0");assertThat(answers.findOne(sid,shortId).getAutoScore()).isNull();List<Long> answerIds=answers.findBySubmissionId(sid).stream().map(Answers::getId).toList();studentExams.autoSubmitExpired();assertThat(answers.findBySubmissionId(sid).stream().map(Answers::getId).toList()).containsExactlyElementsOf(answerIds);assertThat(submissions.getById(sid).getTotalScore()).isEqualByComparingTo("5");}
 @Test void gradingPublicationWorkflowEnforcesOwnershipScoringLocksAndStudentPrivacy()throws Exception{
  Users otherStudentUser=users.findByUsername("student_demo_2");CourseStudents otherMembership=new CourseStudents();otherMembership.setCourseId(exams.getById(examId).getCourseId());otherMembership.setStudentId(otherStudentUser.getId());otherMembership.setStatus(1);memberships.save(otherMembership);String otherStudent=jwt.generate(otherStudentUser);Long otherSid=call(post("/api/student/exams/"+examId+"/enter"),null,otherStudent,200).path("data").path("submissionId").asLong();
  Long sid=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data").path("submissionId").asLong();call(put("/api/student/submissions/"+sid+"/answers/"+singleId),Map.of("answerContent","A"),student,200);call(put("/api/student/submissions/"+sid+"/answers/"+shortId),Map.of("answerContent","JWT由签名保护"),student,200);call(post("/api/student/submissions/"+sid+"/submit"),null,student,200);Answers shortAnswer=answers.findOne(sid,shortId),singleAnswer=answers.findOne(sid,singleId);
  AiGradingResults suggestion=new AiGradingResults();suggestion.setAnswerId(shortAnswer.getId());suggestion.setAiScore(new BigDecimal("7"));suggestion.setAiReason("命中签名");suggestion.setAiComment("补充令牌签发流程");suggestion.setMatchedPoints("[\"签名\"]");suggestion.setMissingPoints("[\"令牌\"]");suggestion.setStatus("SUCCESS");aiResults.save(suggestion);
  Users other=new Users();other.setUsername("grading_other_"+UUID.randomUUID().toString().substring(0,8));other.setName("其他教师");other.setRole("TEACHER");other.setStatus(1);other.setPasswordHash(users.findByUsername("teacher_demo").getPasswordHash());users.save(other);String otherTeacher=jwt.generate(other);
  call(get("/api/teacher/grading/exams/"+examId+"/submissions"),null,otherTeacher,403);call(get("/api/teacher/grading/submissions/"+sid),null,otherTeacher,403);
  JsonNode listed=call(get("/api/teacher/grading/exams/"+examId+"/submissions"),null,teacher,200).path("data").get(0);assertThat(listed.path("studentName").asText()).isEqualTo("测试学生一");assertThat(listed.path("status").asText()).isEqualTo("SUBMITTED");assertThat(listed.path("gradingStatus").asText()).isEqualTo("PENDING");assertThat(listed.path("submitTime").isTextual()).isTrue();
  JsonNode paper=call(get("/api/teacher/grading/submissions/"+sid),null,teacher,200);assertThat(paper.toString()).contains("JWT由签名保护","\"autoScore\":5","\"aiScore\":7","命中签名","签名","令牌","补充令牌签发流程");
  call(post("/api/teacher/grading/submissions/"+sid+"/publish"),null,teacher,409);call(put("/api/teacher/grading/answers/"+singleAnswer.getId()+"/review"),Map.of("teacherScore",1,"teacherComment","不得人工覆盖单选题"),teacher,400);call(put("/api/teacher/grading/answers/"+shortAnswer.getId()+"/review"),Map.of("teacherScore",11,"teacherComment","超分"),teacher,400);
  paper=call(put("/api/teacher/grading/answers/"+shortAnswer.getId()+"/review"),Map.of("teacherScore",8,"teacherComment","人工复核完成"),teacher,200);assertThat(paper.path("data").path("totalScore").decimalValue()).isEqualByComparingTo("13");assertThat(answers.getById(shortAnswer.getId()).getGradingStatus()).isEqualTo("REVIEWED");
  call(put("/api/teacher/grading/submissions/"+sid+"/comment"),Map.of("teacherComment","最终评语"),teacher,200);JsonNode published=call(post("/api/teacher/grading/submissions/"+sid+"/publish"),null,teacher,200).path("data");assertThat(published.path("scorePublished").asBoolean()).isTrue();assertThat(published.path("publishedAt").isTextual()).isTrue();assertThat(exams.getById(examId).getStatus()).isEqualTo("PUBLISHED");call(put("/api/student/submissions/"+otherSid+"/answers/"+singleId),Map.of("answerContent","A"),otherStudent,200);
  call(put("/api/teacher/grading/answers/"+shortAnswer.getId()+"/review"),Map.of("teacherScore",2,"teacherComment","偷偷改分"),teacher,409);call(put("/api/teacher/grading/submissions/"+sid+"/comment"),Map.of("teacherComment","偷偷改评语"),teacher,409);call(post("/api/teacher/grading/answers/"+shortAnswer.getId()+"/ai-grade"),null,teacher,409);call(post("/api/teacher/grading/submissions/"+sid+"/publish"),null,teacher,409);assertThat(answers.getById(shortAnswer.getId()).getTeacherScore()).isEqualByComparingTo("8");
  assertThat(answers.getById(shortAnswer.getId()).getTeacherComment()).isEqualTo("人工复核完成");assertThat(submissions.getById(sid).getTeacherComment()).isEqualTo("最终评语");assertThat(aiResults.findByAnswerId(shortAnswer.getId()).getAiScore()).isEqualByComparingTo("7");call(get("/api/student/results/"+sid),null,otherStudent,404);JsonNode result=call(get("/api/student/results/"+sid),null,student,200);assertThat(result.path("data").path("examTitle").asText()).isEqualTo("可作答考试");assertThat(result.path("data").path("totalScore").decimalValue()).isEqualByComparingTo("13");assertThat(result.path("data").path("teacherComment").asText()).isEqualTo("最终评语");assertThat(result.path("data").path("publishedAt").isTextual()).isTrue();assertThat(result.toString()).doesNotContain("referenceAnswer","scoringPoints","aiReason","matchedPoints","missingPoints");
 }
}
